/** Each event type, and the object its `data.object` holds. */
export interface EventObjects {
  "checkout.created": CheckoutSession;
  "checkout.expired": CheckoutSession;
  "payment.created": Payment;
  "payment.processing": Payment;
  "payment.requires_action": Payment;
  "payment.succeeded": Payment;
  "payment.failed": Payment;
  "payment.cancelled": Payment;
  "payment.refunded": Payment;
  "payment.disputed": Payment;
  "payment.risk_cleared": Payment;
  "invoice.created": Invoice;
  "invoice.paid": Invoice;
  "invoice.expired": Invoice;
  "subscription.created": Subscription;
  "subscription.renewal_upcoming": Subscription;
  "subscription.renewed": Subscription;
  "subscription.reactivated": Subscription;
  "subscription.past_due": Subscription;
  "subscription.expired": Subscription;
  "subscription.cancelled": Subscription;
  "subscription.updated": Subscription;
  "payout.created": Payout;
  "payout.completed": Payout;
  "payout.failed": Payout;
  "webhook.test": WebhookTestObject;
}

export type EventType = keyof EventObjects;

interface EventFields<T extends EventType> {
  id: string;
  /** payment.succeeded, invoice.paid, checkout.expired, … */
  type: T;
  created: number;
  livemode: boolean;
  api_version: string;
  data: {
    /** The object as it was when the event happened, complete enough to act on alone. */
    object: EventObjects[T];
  };
}

/** An event as delivered to your webhook endpoint. Check it with `webhooks.verify`, then narrow it by `type`. */
export type WebhookEvent<T extends EventType = EventType> = { [K in T]: EventFields<K> }[T];

/** An event as `GET /v1/events` returns it: the delivered body, with `object: "event"`. */
export type ShipBillEvent<T extends EventType = EventType> = { [K in T]: EventFields<K> & { object: "event" } }[T];

