export class InvoicesResource {
  constructor(private readonly api: Requester) {}

  /** Export invoices for your accountant. Every invoice and credit note issued from `from` to `to` (in your profile's timezone), as a ZIP of their PDFs with an index.csv, or the CSV alone. Made in the background: until the file is ready the answer is 409 `invoice_export_pending` with Retry-After, so call again. The same request within an hour gets the same file. A closed month's ZIP is the one kept when it was closed. A range with nothing issued in it answers 409 `nothing_to_export`. */
  export(params: ExportInvoicesParams, options?: RequestOptions): Promise<Uint8Array> {
    return this.api.request<Uint8Array>("GET", `/invoices/export`, { query: params, options, binary: true });
  }

  /** List invoices */
  list(params: ListInvoicesParams = {}, options?: RequestOptions): ListPromise<Invoice> {
    return this.api.list<Invoice>(`/invoices`, params, options);
  }

  /** Retrieve an invoice */
  retrieve(id: string, options?: RequestOptions): Promise<Invoice> {
    return this.api.request<Invoice>("GET", `/invoices/${encodeURIComponent(id)}`, { options });
  }

  /** Download an invoice's PDF. Drawn when the invoice is paid or changes, and otherwise on the first request; the answer is 409 `invoice_pdf_pending` only while a paid or refunded invoice's draw is still running. */
  pdf(id: string, options?: RequestOptions): Promise<Uint8Array> {
    return this.api.request<Uint8Array>("GET", `/invoices/${encodeURIComponent(id)}/pdf`, { options, binary: true });
  }

  /** Void an open invoice. It can no longer be paid, and its checkout closes. A paid or expired invoice can't be voided. */
  void(id: string, options?: RequestOptions): Promise<Invoice> {
    return this.api.request<Invoice>("POST", `/invoices/${encodeURIComponent(id)}/void`, { options });
  }
}

