/** Every resource of the API, as properties of the client. */
export class ShipBillResources {
  readonly checkout: {
    readonly sessions: CheckoutSessionsResource;
  };
  readonly paymentIntents: PaymentIntentsResource;
  readonly payments: PaymentsResource;
  readonly refunds: RefundsResource;
  readonly invoices: InvoicesResource;
  readonly creditNotes: CreditNotesResource;
  readonly customers: CustomersResource;
  readonly events: EventsResource;
  readonly products: ProductsResource;
  readonly productCategories: ProductCategoriesResource;
  readonly paymentLinks: PaymentLinksResource;
  readonly coupons: CouponsResource;
  readonly webhookEndpoints: WebhookEndpointsResource;
  readonly subscriptions: SubscriptionsResource;
  readonly test: {
    readonly subscriptions: TestSubscriptionsResource;
  };

  constructor(api: Requester) {
    this.checkout = {
      sessions: new CheckoutSessionsResource(api),
    };
    this.paymentIntents = new PaymentIntentsResource(api);
    this.payments = new PaymentsResource(api);
    this.refunds = new RefundsResource(api);
    this.invoices = new InvoicesResource(api);
    this.creditNotes = new CreditNotesResource(api);
    this.customers = new CustomersResource(api);
    this.events = new EventsResource(api);
    this.products = new ProductsResource(api);
    this.productCategories = new ProductCategoriesResource(api);
    this.paymentLinks = new PaymentLinksResource(api);
    this.coupons = new CouponsResource(api);
    this.webhookEndpoints = new WebhookEndpointsResource(api);
    this.subscriptions = new SubscriptionsResource(api);
    this.test = {
      subscriptions: new TestSubscriptionsResource(api),
    };
  }
}
